function failx($m,$s=400){http_response_code($s);header('Content-Type: application/json; charset=utf-8');echo json_encode(['error'=>$m],JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);exit;}function userx(){global $CONFIG;$h=$_SERVER['HTTP_AUTHORIZATION']??'';if(!preg_match('/Bearer\s+(.+)/i',$h,$m))failx('توکن نامعتبر است',401);$p=Jwt::verify(trim($m[1]),$CONFIG['jwt_secret']);if(!$p)failx('توکن منقضی یا نامعتبر است',401);$u=Db::one("SELECT u.id,u.is_active,r.title role_title,r.is_admin FROM users u JOIN roles r ON r.id=u.role_id WHERE u.id=?",[$p['sub']]);if(!$u||!$u['is_active'])failx('کاربر نامعتبر است',401);return $u;}function adminx($u){return !empty($u['is_admin'])||in_array($u['role_title']??'', ['مدیر کل','رییس اداره بازرسی','نیروی اداری ارشد'],true);}
function jal($dt){try{$d=new DateTime($dt,new DateTimeZone('Asia/Tehran'));$gy=(int)$d->format('Y')-1600;$gm=(int)$d->format('n')-1;$gd=(int)$d->format('j')-1;$md=[31,28,31,30,31,30,31,31,30,31,30,31];$y=$gy+1600;$md[1]=((($y%4===0)&&($y%100!==0))||$y%400===0)?29:28;$gdn=365*$gy+intdiv($gy+3,4)-intdiv($gy+99,100)+intdiv($gy+399,400);for($i=0;$i<$gm;$i++)$gdn+=$md[$i];$gdn+=$gd;$jdn=$gdn-79;$jnp=intdiv($jdn,12053);$jdn%=12053;$jy=979+33*$jnp+4*intdiv($jdn,1461);$jdn%=1461;if($jdn>=366){$jy+=intdiv($jdn-1,365);$jdn=($jdn-1)%365;}$jm=$jdn<186?1+intdiv($jdn,31):7+intdiv($jdn-186,30);$jd=1+($jdn<186?$jdn%31:($jdn-186)%30);return sprintf('%04d/%02d/%02d %s',$jy,$jm,$jd,$d->format('H:i:s'));}catch(Throwable $e){return $dt;}}
function col($n){$s='';do{$s=chr(65+$n%26).$s;$n=intdiv($n,26)-1;}while($n>=0);return $s;}function xe($v){return htmlspecialchars((string)($v??''),ENT_XML1|ENT_QUOTES,'UTF-8');}function cell($ref,$value,$style=0){return '<c r="'.$ref.'" t="inlineStr" s="'.$style.'"><is><t>'.xe($value).'</t></is></c>';}function numcell($ref,$value,$style=0){return '<c r="'.$ref.'" t="n" s="'.$style.'"><v>'.xe($value).'</v></c>';}
