 $paths=[];if(!empty($r['location_photo_path']))$paths[]=['path'=>$r['location_photo_path'],'col'=>13,'row'=>$rn,'prefix'=>'station'];foreach(array_filter(explode('||',(string)($r['sign_photos']??''))) as $p)$paths[]=['path'=>$p,'col'=>14,'row'=>$rn,'prefix'=>'sign'];$signIndex=0;foreach($paths as $p){$abs=__DIR__.'/..'.$p['path'];if(!is_file($abs))continue;$bin=@file_get_contents($abs);if(!$bin)continue;$ext=strtolower(pathinfo($abs,PATHINFO_EXTENSION));$mime=$ext==='png'?'image/png':'image/jpeg';$mediaName='xl/media/image'.$imageId.'.'.$ext;$z->addFromString($mediaName,$bin);$media[]=['id'=>$imageId,'name'=>$mediaName,'mime'=>$mime,'ext'=>$ext];$fromCol=$p['col'];$toCol=$fromCol+1;$fromRow=$rn-1;$toRow=$rn; $anchors[]=['id'=>$imageId,'fromCol'=>$fromCol,'toCol'=>$toCol,'fromRow'=>$fromRow,'toRow'=>$toRow,'name'=>$p['prefix'].'-'.$i.'-'.$signIndex];$imageId++;$signIndex++;}}
